function solve(state):
    if state is a complete answer:
        record it
        return

    for each choice available from state:
        if choice is not allowed:
            continue          # prune: never build anything below here

        apply choice          # choose
        solve(state)          # explore
        undo choice           # un-choose

for (let i = start; i < nums.length; i++) {
  current.push(nums[i]);
  solve(i + 1);
  // current.pop();   <-- forgotten
}

function subsets(nums) {
  const answers = [];
  const current = [];

  function solve(start) {
    answers.push([...current]);        // a copy, see the note below

    for (let i = start; i < nums.length; i++) {
      current.push(nums[i]);           // choose
      solve(i + 1);                    // explore
      current.pop();                   // un-choose
    }
  }

  solve(0);
  return answers;
}

