void solve(const vector<int>& nums, int start,
           vector<int>& current, vector<vector<int>>& answers) {
    answers.push_back(current);        // a copy, see the note below

    for (int i = start; i < (int)nums.size(); i++) {
        current.push_back(nums[i]);    // choose
        solve(nums, i + 1, current, answers);
        current.pop_back();            // un-choose
    }
}
